                    }
                }

                if (obj.ContainsKey("name"))
                {
                    Our.Item instance = ItemFrom(
                        node, out error);
                    if (error != null)
                    {
                        return default!;
                    }
                    return Our.WideUnion.FromItem(instance);
                }

                error = new Reporting.Error(
                    "Could not determine the concrete type of the union WideUnion " +
                    "from the given JSON object; none of its implementers matched");
                return default!;
            }  // public static Our.WideUnion WideUnionFrom

            /// <summary>
            /// Deserialize an instance of Something from <paramref name="node" />.
            /// </summary>
            /// <param name="node">JSON node to be parsed</param>
            /// <param name="error">Error, if any, during the deserialization</param>
            internal static Our.Something SomethingFrom(
                Nodes.JsonNode? node,
                out Reporting.Error? error)
            {
                error = null;

                Nodes.JsonObject? obj = node as Nodes.JsonObject;
                if (obj == null)
                {
                    error = new Reporting.Error(
                        $"Expected a JsonObject representing Something, but got {Describe(node)}");
                    return default!;
                }

                string? theText = null;
                long? theNumber = null;
                bool? theFlag = null;
                Kind? theKind = null;
                string? theCode = null;
                IItem? theItem = null;
                IParent? theParent = null;
                List<IParent>? theParents = null;
                List<string>? theTexts = null;
                string? theOptionalText = null;
                Kind? theOptionalKind = null;
                IParent? theOptionalParent = null;
                List<string>? theOptionalTexts = null;
                byte[]? theOptionalData = null;
                ParentOrItem? theOptionalMember = null;

                foreach (var keyValue in obj)
                {
                    switch (keyValue.Key)
                    {
                        case "text":
                            theText = StringFrom(
                                keyValue.Value, out error);
                            break;
                        case "number":
                            theNumber = LongFrom(
                                keyValue.Value, out error);
                            break;
                        case "flag":
                            theFlag = BoolFrom(
                                keyValue.Value, out error);
                            break;
                        case "kind":
                            theKind = KindFrom(
                                keyValue.Value, out error);
                            break;
                        case "code":
                            theCode = StringFrom(
                                keyValue.Value, out error);
                            break;
                        case "item":
                            theItem = ItemFrom(
                                keyValue.Value, out error);
                            break;
                        case "parent":
                            theParent = IParentFrom(
                                keyValue.Value, out error);
                            break;
                        case "parents":
                            theParents = Parse_ListOf_IParent(
                                keyValue.Value, out error);
                            break;
                        case "texts":
                            theTexts = Parse_ListOf_string(
                                keyValue.Value, out error);
                            break;
                        case "optionalText":
                            theOptionalText = StringFrom(
                                keyValue.Value, out error);
                            break;
                        case "optionalKind":
                            theOptionalKind = KindFrom(
                                keyValue.Value, out error);
                            break;
                        case "optionalParent":
                            theOptionalParent = IParentFrom(
                                keyValue.Value, out error);
                            break;
                        case "optionalTexts":
                            theOptionalTexts = Parse_ListOf_string(
                                keyValue.Value, out error);
                            break;
                        case "optionalData":
                            theOptionalData = BytesFrom(
                                keyValue.Value, out error);
                            break;
                        case "optionalMember":
                            theOptionalMember = ParentOrItemFrom(
                                keyValue.Value, out error);
                            break;
                        default:
                            error = new Reporting.Error(
                                $"Unexpected property: {keyValue.Key}");
                            return default!;
                    }

                    if (error != null)
                    {
                        error.PrependSegment(
                            new Reporting.NameSegment(
                                keyValue.Key));
                        return default!;
                    }
                }

                if (theText == null)
                {
                    error = new Reporting.Error(
                        "Required property \"text\" is missing");
                    return default!;
                }

                if (theNumber == null)
                {
                    error = new Reporting.Error(
                        "Required property \"number\" is missing");
                    return default!;
                }

                if (theFlag == null)
                {
                    error = new Reporting.Error(
                        "Required property \"flag\" is missing");
                    return default!;
                }

                if (theKind == null)
                {
                    error = new Reporting.Error(
                        "Required property \"kind\" is missing");
                    return default!;
                }

                if (theCode == null)
                {
                    error = new Reporting.Error(
                        "Required property \"code\" is missing");
                    return default!;
                }

                if (theItem == null)
                {
                    error = new Reporting.Error(
                        "Required property \"item\" is missing");
                    return default!;
                }

                if (theParent == null)
                {
                    error = new Reporting.Error(
                        "Required property \"parent\" is missing");
                    return default!;
                }

                if (theParents == null)
                {
                    error = new Reporting.Error(
                        "Required property \"parents\" is missing");
                    return default!;
                }

                if (theTexts == null)
                {
                    error = new Reporting.Error(
                        "Required property \"texts\" is missing");
                    return default!;
                }

                return new Our.Something(
                    theText
                         ?? throw new System.InvalidOperationException(
                            "Unexpected null, had to be handled before"),
                    theNumber
                         ?? throw new System.InvalidOperationException(
                            "Unexpected null, had to be handled before"),
                    theFlag
                         ?? throw new System.InvalidOperationException(
                            "Unexpected null, had to be handled before"),
                    theKind
                         ?? throw new System.InvalidOperationException(
                            "Unexpected null, had to be handled before"),
                    theCode
                         ?? throw new System.InvalidOperationException(
                            "Unexpected null, had to be handled before"),
                    theItem
                         ?? throw new System.InvalidOperationException(
                            "Unexpected null, had to be handled before"),
                    theParent
                         ?? throw new System.InvalidOperationException(
                            "Unexpected null, had to be handled before"),
                    theParents
                         ?? throw new System.InvalidOperationException(
                            "Unexpected null, had to be handled before"),
                    theTexts
                         ?? throw new System.InvalidOperationException(
                            "Unexpected null, had to be handled before"),
                    theOptionalText,
                    theOptionalKind,
                    theOptionalParent,
                    theOptionalTexts,
                    theOptionalData,
                    theOptionalMember);
            }  // internal static SomethingFrom
        }  // public static class DeserializeImplementation

        /// <summary>
        /// Represent a critical error during the deserialization.
        /// </summary>
        public class Exception : System.Exception
        {
            public readonly string Path;
            public readonly string Cause;
            public Exception(string path, string cause)
                : base($"{cause} at: {path}")
            {
                Path = path;
                Cause = cause;
            }
        }

        /// <summary>
        /// Represent a critical error during the serialization.
        /// </summary>
        public class SerializationException : System.Exception
        {
            public readonly string Path;
            public readonly string Cause;
            public SerializationException(string path, string cause)
                : base($"{cause} at: {path}")
            {
                Path = path;
                Cause = cause;
            }
        }

        /// <summary>
        /// Signal a failure of the serialization, carrying the path to the culprit.
        /// </summary>
        /// <remarks>
        /// The path is built as the stack unwinds -- every container prepends the one
        /// segment it knows, the property its name and the list the index of the item
        /// -- which is why this can not be a <see cref="SerializationException" />
        /// already: that one renders its message in its constructor, so its path has
        /// to be complete by then. <see cref="Serialize.ToJsonObject" /> renders and
        /// converts.
        /// </remarks>
        internal class SerializationFailure : System.Exception
        {
            public readonly Reporting.Error Error;
            public SerializationFailure(Reporting.Error error)
                : base(error.Cause)
            {
                Error = error;
            }
        }

