        internal class Transformer
            : Visitation.AbstractTransformer<Nodes.JsonObject>
        {
            /// <summary>
            /// Dispatch the serialization over the run-time type of an instance.
            /// </summary>
            /// <remarks>
            /// The transformer carries no state, so a single instance serves the whole
            /// program. No field initializer reads it, only
            /// <see cref="TransformIClass" /> does, so it does not matter where among
            /// the serializers it is initialized.
            /// </remarks>
            [CodeAnalysis.SuppressMessage("ReSharper", "InconsistentNaming")]
            private static readonly Transformer _instance = new Transformer();

            /// <summary>
            /// Serialize <paramref name="that" /> into a JSON object.
            /// </summary>
            /// <remarks>
            /// Which JSON object that is, is decided by the run-time type of
            /// <paramref name="that" />, so this one serializer serves every abstract
            /// class and every concrete class with descendants, as well as the item of
            /// a list or of a tuple of any of them.
            /// </remarks>
            internal static Nodes.JsonObject TransformIClass(Our.IClass that)
            {
                return _instance.Transform(that);
            }

            /// <summary>
            /// Convert <paramref name="that" /> 64-bit floating-point number to a JSON
            /// value.
            /// </summary>
            /// <param name="that">value to be converted</param>
            /// <exception name="SerializationFailure">
            /// Thrown if <paramref name="that" /> is not finite. JSON knows neither
            /// an infinity nor a not-a-number, so we refuse them here instead of
            /// leaving it to <c>System.Text.Json</c>, which throws much later -- when
            /// the caller writes the document out -- and says nothing about where
            /// the offending value sat.
            /// </exception>
            [CodeAnalysis.SuppressMessage("ReSharper", "UnusedMember.Local")]
            private static Nodes.JsonValue ToJsonValue(double that)
            {
                if (!System.Double.IsFinite(that))
                {
                    throw new SerializationFailure(
                        new Reporting.Error(
                            "JSON knows neither an infinity nor a not-a-number, so " +
                            $"the value can not be serialized: {that}"));
                }
                return Nodes.JsonValue.Create(that);
            }

            /// <summary>
            /// Convert <paramref name="that" /> 64-bit long integer to a JSON value.
            /// </summary>
            /// <param name="that">value to be converted</param>
            /// <exception name="SerializationFailure">
            /// Thrown if <paramref name="that" /> lies outside the safe integer range,
            /// see <see cref="Common.IsSafeInteger(long)" />.
            /// </exception>
            [CodeAnalysis.SuppressMessage("ReSharper", "UnusedMember.Local")]
            private static Nodes.JsonValue ToJsonValue(long that)
            {
                if (!Common.IsSafeInteger(that))
                {
                    throw new SerializationFailure(
                        new Reporting.Error(
                            Verification.UnsafeIntegerMessage(that)));
                }
                return Nodes.JsonValue.Create(that);
            }

            /// <summary>
            /// Serialize the named union <paramref name="that" /> into a JSON object.
            /// </summary>
            /// <remarks>
            /// A named union is not an <see cref="Our.IClass" />, so it can not be
            /// dispatched by <see cref="TransformIClass" />. Dispatching over the
            /// common, non-generic <see cref="Our.IUnion" /> means we need only this one
            /// serializer for *all* named unions, and not one per union.
            ///
            /// Should a named union ever be allowed to flatten primitive or enumeration
            /// alternatives, only the body of this method has to change (to dispatch on
            /// the underlying value's kind) -- every call site stays the same.
            /// </remarks>
            private static Nodes.JsonObject TransformIUnion(Our.IUnion that)
            {
                return TransformIClass(that.Underlying);
            }

            /// <summary>
            /// Serialize <paramref name="that" /> into a JSON value.
            /// </summary>
            /// <remarks>
            /// This is the shape shared by every serialization step, so that the steps
            /// can be composed. Unlike the XML side, no combinator is needed to frame
            /// the value -- a JSON value stands on its own -- so the only composition
            /// is over the items of a list or of a tuple.
            /// </remarks>
            /// <typeparam name="T">Type of the value to be serialized</typeparam>
            private delegate Nodes.JsonNode? Serializer<in T>(T that);

            /// <summary>
            /// Convert <paramref name="that" /> to a JSON value.
            /// </summary>
            private static Nodes.JsonValue ToJsonValue(bool that)
            {
                return Nodes.JsonValue.Create(that);
            }

            /// <summary>
            /// Convert <paramref name="that" /> to a JSON value.
            /// </summary>
            private static Nodes.JsonValue ToJsonValue(string that)
            {
                return Nodes.JsonValue.Create(that)
                    ?? throw new System.InvalidOperationException(
                        "Unexpected null JSON value from a non-null string");
            }

            /// <summary>
            /// Convert <paramref name="that" /> to a JSON value.
            /// </summary>
            private static Nodes.JsonValue ToJsonValue(byte[] that)
            {
                return Nodes.JsonValue.Create(System.Convert.ToBase64String(that))
                    ?? throw new System.InvalidOperationException(
                        "Unexpected null JSON value from a non-null string");
            }

            /// <summary>
            /// Compose the serializer of a list whose items are serialized with
            /// <paramref name="serializeItem" />.
            /// </summary>
            /// <remarks>
            /// This is shared by all the list-typed properties. The composition is
            /// performed once, when the field holding the result is initialized, so
            /// serializing a list allocates nothing besides the JSON array itself.
            ///
            /// The parameter is a <c>List</c> rather than an <c>IEnumerable</c> so that
            /// the iteration does not box the enumerator -- which is also the type that
            /// every list-typed property actually has.
            /// </remarks>
            /// <typeparam name="T">Type of a single list item</typeparam>
            private static Serializer<List<T>> SerializeList<T>(
                Serializer<T> serializeItem)
            {
                return (that) =>
                {
                    var result = new Nodes.JsonArray();
                    int i = 0;
                    foreach (T item in that)
                    {
                        try
                        {
                            result.Add(serializeItem(item));
                        }
                        catch (SerializationFailure failure)
                        {
                            failure.Error.PrependSegment(
                                new Reporting.IndexSegment(i));
                            throw;
                        }
                        i++;
                    }
                    return result;
                };
            }

            private static readonly Serializer<List<IParent>> Serialize_ListOf_IParent = (
                SerializeList<IParent>(
                    TransformIClass));

            private static readonly Serializer<List<string>> Serialize_ListOf_string = (
                SerializeList<string>(
                    ToJsonValue));

            private static readonly Serializer<string> Serialize_string = ToJsonValue;

            private static readonly Serializer<long> Serialize_long = ToJsonValue;

            private static readonly Serializer<bool> Serialize_bool = ToJsonValue;

            private static readonly Serializer<Kind> Serialize_Kind = Serialize.KindToJsonValue;

            private static readonly Serializer<Our.IClass> Serialize_IClass = TransformIClass;

            private static readonly Serializer<byte[]> Serialize_bytes = ToJsonValue;

            private static readonly Serializer<Our.IUnion> Serialize_IUnion = TransformIUnion;

            /// <summary>
            /// Set the property <paramref name="jsonName" /> of
            /// <paramref name="result" /> to <paramref name="that" />, serialized by
            /// <paramref name="serialize" />.
            /// </summary>
            /// <remarks>
            /// <paramref name="propertyName" /> names the property on the path of
            /// a failure. It is the C# property, and not the JSON one: a serialization
            /// error is reported on an <em>instance</em>, which the caller holds, and
            /// not on a document which has not been written yet.
            /// </remarks>
            /// <typeparam name="T">Type of the value to serialize</typeparam>
            private static void SetProperty<T>(
                Nodes.JsonObject result,
                string jsonName,
                string propertyName,
                T that,
                Serializer<T> serialize)
            {
                try
                {
                    result[jsonName] = serialize(that);
                }
                catch (SerializationFailure failure)
                {
                    failure.Error.PrependSegment(
                        new Reporting.NameSegment(propertyName));
                    throw;
                }
            }

            public override Nodes.JsonObject TransformItem(
                Our.IItem that
            )
            {
                var result = new Nodes.JsonObject();

                SetProperty(result, "name", "Name", that.Name, Serialize_string);

                return result;
            }

            public override Nodes.JsonObject TransformChildA(
                Our.IChildA that
            )
            {
                var result = new Nodes.JsonObject();

                if (that.OptionalText != null)
                {
                    SetProperty(
                        result,
                        "optionalText",
                        "OptionalText",
                        that.OptionalText,
                        Serialize_string);
                }

                SetProperty(result, "aOnly", "AOnly", that.AOnly, Serialize_long);

                result["modelType"] = "ChildA";

                return result;
            }

            public override Nodes.JsonObject TransformChildB(
                Our.IChildB that
            )
            {
                var result = new Nodes.JsonObject();

                if (that.OptionalText != null)
                {
                    SetProperty(
                        result,
                        "optionalText",
                        "OptionalText",
                        that.OptionalText,
                        Serialize_string);
                }

                SetProperty(result, "bOnly", "BOnly", that.BOnly, Serialize_long);

                result["modelType"] = "ChildB";

                return result;
            }

            public override Nodes.JsonObject TransformSomething(
                Our.ISomething that
            )
            {
                var result = new Nodes.JsonObject();

                SetProperty(result, "text", "Text", that.Text, Serialize_string);

                SetProperty(result, "number", "Number", that.Number, Serialize_long);

                SetProperty(result, "flag", "Flag", that.Flag, Serialize_bool);

                SetProperty(result, "kind", "Kind", that.Kind, Serialize_Kind);

                SetProperty(result, "code", "Code", that.Code, Serialize_string);

                SetProperty(result, "item", "Item", that.Item, Serialize_IClass);

                SetProperty(result, "parent", "Parent", that.Parent, Serialize_IClass);

                SetProperty(result, "parents", "Parents", that.Parents, Serialize_ListOf_IParent);

                SetProperty(result, "texts", "Texts", that.Texts, Serialize_ListOf_string);

                if (that.OptionalText != null)
                {
                    SetProperty(
                        result,
                        "optionalText",
                        "OptionalText",
                        that.OptionalText,
                        Serialize_string);
                }

                if (that.OptionalKind.HasValue)
                {
                    SetProperty(
                        result,
                        "optionalKind",
                        "OptionalKind",
                        that.OptionalKind.Value,
                        Serialize_Kind);
                }

                if (that.OptionalParent != null)
                {
                    SetProperty(
                        result,
                        "optionalParent",
                        "OptionalParent",
                        that.OptionalParent,
                        Serialize_IClass);
                }

                if (that.OptionalTexts != null)
                {
                    SetProperty(
                        result,
                        "optionalTexts",
                        "OptionalTexts",
                        that.OptionalTexts,
                        Serialize_ListOf_string);
                }

                if (that.OptionalData != null)
                {
                    SetProperty(
                        result,
                        "optionalData",
                        "OptionalData",
                        that.OptionalData,
                        Serialize_bytes);
                }

                if (that.OptionalMember != null)
                {
                    SetProperty(
                        result,
                        "optionalMember",
                        "OptionalMember",
                        that.OptionalMember,
                        Serialize_IUnion);
                }

                return result;
            }
        }  // internal class Transformer

        /// <summary>
        /// Serialize instances of meta-model classes to JSON elements.
        /// </summary>
        /// <example>
        /// Here is an example how to serialize an instance of Item:
        /// <code>
        /// var anInstance = new Our.Item(
        ///     // ... some constructor arguments ...
        /// );
        /// System.Text.Json.Nodes.JsonObject element = (
        ///     Serialize.ToJsonObject(
        ///         anInstance));
        /// </code>
        /// </example>
        public static class Serialize
        {
            /// <summary>
            /// Serialize an instance of the meta-model into a JSON object.
            /// </summary>
            /// <exception cref="SerializationException">
